// ===== MONITOR ORG CASCADER =====
let _treeActiveCenter = null;
let _treeSelectedStation = null;

function buildOrgCascaderList(filter) {
  var d = window._MONITOR_DATA || {};
  var centers = d.opsCenters || [];
  var rootName = d.rootName || '小水电集控中心';
  var list = document.getElementById('orgCascaderList');
  if (!list) return;
  var kw = (filter||'').toLowerCase().trim();

  // Compute match state per node
  var rootMatch = !kw || rootName.toLowerCase().indexOf(kw) >= 0;
  var centerStates = [];
  var anyChildMatch = false;
  centers.forEach(function(c) {
    var cname = esc(c.companyName||'');
    var cMatch = !kw || cname.toLowerCase().indexOf(kw) >= 0;
    var stMatches = [];
    (c.children||[]).forEach(function(s) {
      var sm = esc(s.companyName||'').toLowerCase().indexOf(kw) >= 0;
      if (sm) anyChildMatch = true;
      stMatches.push({s:s, match:!kw || sm});
    });
    if (cMatch) anyChildMatch = true;
    centerStates.push({c:c, match:cMatch, stations:stMatches});
  });

  function csAny(s){return s.some(function(x){return x.match;});}
  var html = '';
  if (!kw || rootMatch || anyChildMatch) {
    var rActive = !_treeActiveCenter && !_treeSelectedStation;
    var rOpen = !kw || rActive || rootMatch || anyChildMatch;
    html += '<div class="cascader-item lv0'+(rActive?' active':'')+'" data-level="0" data-id="_group">'
      +'<span class="cd-arrow'+(rOpen?' open':'')+'" onclick="toggleTreeChildren(this)">&#9654;</span>'
      +'<span class="cd-label" onclick="selectOrgItem(\'_group\',0,\''+esc(rootName)+'\')">'+highlightMatch(esc(rootName),kw)+'</span>'
      +'<span class="cd-badge">'+centers.length+' 中心</span>'
      +'</div>';
    html += '<div class="cd-children'+(rOpen?' open':'')+'">';

    centerStates.forEach(function(cs) {
      var hasSm = csAny(cs.stations);
      if (kw && !cs.match && !hasSm) return;
      var cn = esc(cs.c.companyName||'');
      var cActive = _treeActiveCenter===cs.c.id && !_treeSelectedStation;
      var cOpen = !kw || cActive || cs.match || hasSm;
      html += '<div class="cascader-item lv1'+(cActive?' active':'')+'" data-level="1" data-id="'+cs.c.id+'">'
        +'<span class="cd-arrow'+(cOpen?' open':'')+'" onclick="toggleTreeChildren(this)">&#9654;</span>'
        +'<span class="cd-label" onclick="selectOrgItem(\''+cs.c.id+'\',1,\''+cn+'\')">'+highlightMatch(cn,kw)+'</span>'
        +'<span class="cd-badge">'+cs.stations.length+' 站</span>'
        +'</div>';
      html += '<div class="cd-children'+(cOpen?' open':'')+'">';

      cs.stations.forEach(function(st) {
        if (kw && !st.match) return;
        var sn = esc(st.s.companyName||'');
        var sActive = _treeSelectedStation===st.s.id;
        html += '<div class="cascader-item lv2'+(sActive?' active':'')+'" data-level="2" data-id="'+st.s.id+'" data-cid="'+cs.c.id+'">'
          +'<span class="cd-arrow leaf">&#9654;</span>'
          +'<span class="cd-label" onclick="selectOrgItem(\''+st.s.id+'\',2,\''+sn+'\',\''+cs.c.id+'\')">'+highlightMatch(sn,kw)+'</span>'
          +'</div>';
      });

      html += '</div>';
    });

    html += '</div>';
  }
  if (!html) html = '<div class="cascader-empty">未找到匹配的组织</div>';
  list.innerHTML = html;
}

function highlightMatch(text, kw) {
  if (!kw) return esc(text);
  var idx = esc(text).toLowerCase().indexOf(kw);
  if (idx < 0) return esc(text);
  var before = esc(text.substring(0, idx));
  var match = esc(text.substring(idx, idx + kw.length));
  var after = esc(text.substring(idx + kw.length));
  return before + '<span class="cascader-highlight">' + match + '</span>' + after;
}

function toggleTreeChildren(arrowEl) {
  arrowEl.classList.toggle('open');
  var children = arrowEl.parentElement.nextElementSibling;
  if (children && children.classList.contains('cd-children')) {
    children.classList.toggle('open');
  }
}

function onBizTypeChange() {
  var sel = document.getElementById('orgBizType');
  if (!sel) return;
  var pageId = sel.value;
  if (typeof navigateTo === 'function') navigateTo(pageId);
}

function toggleOrgCascader() {
  var panel = document.getElementById('orgCascaderPanel');
  var trigger = document.getElementById('orgCascaderTrigger');
  if (!panel || !trigger) return;
  var isOpen = panel.style.display === 'block';
  if (isOpen) {
    panel.style.display = 'none';
    trigger.classList.remove('open');
  } else {
    panel.style.display = 'block';
    trigger.classList.add('open');
    buildOrgCascaderList();
    var inp = document.getElementById('orgCascaderSearch');
    if (inp) { inp.value = ''; inp.focus(); }
  }
}

function filterOrgCascader() {
  var inp = document.getElementById('orgCascaderSearch');
  var kw = inp ? inp.value : '';
  buildOrgCascaderList(kw);
}

function selectOrgItem(id, level, name, centerId) {
  var d = window._MONITOR_DATA || {};
  var rootName = d.rootName || '小水电集控中心';
  var centers = d.opsCenters || [];

  // Build full hierarchical path
  var path = rootName;
  if (level === 1) {
    path += ' / ' + esc(name);
  } else if (level === 2 && centerId) {
    var cn = name;
    for (var i=0; i<centers.length; i++) {
      if (centers[i].id === centerId) { cn = esc(centers[i].companyName) + ' / ' + esc(name); break; }
    }
    path += ' / ' + cn;
  }

  var txt = document.getElementById('orgCascaderText');
  if (txt) { txt.textContent = path; txt.classList.remove('placeholder'); }

  var panel = document.getElementById('orgCascaderPanel');
  var trigger = document.getElementById('orgCascaderTrigger');
  if (panel) panel.style.display = 'none';
  if (trigger) trigger.classList.remove('open');

  buildOrgCascaderList();

  if (level === 0) {
    selectTreeGroup();
  } else if (level === 1) {
    selectOpsCenter(id);
  } else if (level === 2) {
    if (centerId) selectOpsCenter(centerId);
    selectStation(id);
  }
}

// Close cascader on outside click
document.addEventListener('click', function(e) {
  var cascader = document.getElementById('orgCascader');
  if (!cascader) return;
  if (!cascader.contains(e.target)) {
    var panel = document.getElementById('orgCascaderPanel');
    var trigger = document.getElementById('orgCascaderTrigger');
    if (panel) panel.style.display = 'none';
    if (trigger) trigger.classList.remove('open');
  }
});

// ===== USER TABLE FILTER & SORT =====
var _userSortField = null;
var _userSortAsc = true;

function filterUserTable() {
  var searchText = (document.getElementById('userSearchInput')||{}).value || '';
  var roleFilter = (document.getElementById('userRoleFilter')||{}).value || '';
  var statusFilter = (document.getElementById('userStatusFilter')||{}).value || '';
  var tbody = document.getElementById('userTableBody');
  var countEl = document.getElementById('userTableCount');
  var filterCountEl = document.getElementById('userFilterCount');
  if (!tbody) return;
  var rows = tbody.querySelectorAll('tr');
  var visible = 0;
  rows.forEach(function(row) {
    var searchData = row.getAttribute('data-search') || '';
    var role = row.getAttribute('data-role') || '';
    var status = row.getAttribute('data-status') || '';
    var matchSearch = !searchText || searchData.indexOf(searchText.toLowerCase()) !== -1;
    var matchRole = !roleFilter || role === roleFilter;
    var matchStatus = !statusFilter || status === statusFilter;
    if (matchSearch && matchRole && matchStatus) {
      row.style.display = '';
      visible++;
    } else {
      row.style.display = 'none';
    }
  });
  if (countEl) countEl.textContent = '共' + visible + '条记录';
  if (filterCountEl) filterCountEl.textContent = '筛选结果：' + visible + '条';
}

function sortUserTable(field) {
  var tbody = document.getElementById('userTableBody');
  if (!tbody) return;
  var rows = Array.from(tbody.querySelectorAll('tr'));
  if (_userSortField === field) {
    _userSortAsc = !_userSortAsc;
  } else {
    _userSortField = field;
    _userSortAsc = true;
  }
  rows.sort(function(a, b) {
    var va = a.getAttribute('data-search') || '';
    var vb = b.getAttribute('data-search') || '';
    if (field === 'uid') { va = a.cells[0].textContent.trim(); vb = b.cells[0].textContent.trim(); }
    else if (field === 'username') { va = a.cells[1].textContent.trim(); vb = b.cells[1].textContent.trim(); }
    else if (field === 'fullName') { va = a.cells[2].textContent.trim(); vb = b.cells[2].textContent.trim(); }
    else if (field === 'role') { va = a.cells[3].textContent.trim(); vb = b.cells[3].textContent.trim(); }
    else if (field === 'company') { va = a.cells[4].textContent.trim(); vb = b.cells[4].textContent.trim(); }
    else if (field === 'state') { va = a.cells[7].textContent.trim(); vb = b.cells[7].textContent.trim(); }
    else if (field === 'lastLogin') { va = a.cells[8].textContent.trim(); vb = b.cells[8].textContent.trim(); }
    else { va = a.cells[0].textContent.trim(); vb = b.cells[0].textContent.trim(); }
    var cmp = va.localeCompare(vb, 'zh');
    return _userSortAsc ? cmp : -cmp;
  });
  rows.forEach(function(row) { tbody.appendChild(row); });
}

